#include "military_duty_phase.hpp"
#include "military_duty_qualification_capture.hpp"
#include "military_duty_detail.hpp"
#include "military_duty_execution_read.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {using namespace movement_detail;using namespace duty_detail;
Outcome<std::vector<ExactEventPrediction>> predict_military_duty_events(const MilitaryDutyState& state,const MilitaryDutyContext& c,const WorldMoment& current,const WorldMoment& upper){return guard<std::vector<ExactEventPrediction>>([&]{take(make_moment_span(current,upper,c.budget));std::vector<ExactEventPrediction> out;for(const auto& row:state.executions.rows()){const auto& e=row.second;const auto& t=terms(state,row.first);std::optional<WorldMoment> due;SourceRef basis;Integer revision=0;if(e.current_window_ref){const auto* w=state.windows.find(*e.current_window_ref);if(!w||!std::holds_alternative<DutyWindowOpen>(w->state))fail("MilitaryDutyCurrentWindowRequired",row.first);due=w->window.planned_close_at;basis=ref("military_duty_window",w->id);revision=w->window.ordinal;}
if(const auto* s=station(state,row.first))if(!terminal(state,s->id)){auto expiry=until(t,c.budget);if(!due||take(compare_world_moments(expiry,*due,c.budget))<0){due=expiry;basis=ref("military_duty_terms",e.accepted_source_ref);revision=e.service_epoch;}}if(e.actual_binding&&!e.movement_stop&&t.state!=MilitaryDutyPhase::released){const auto expiry=until(t,c.budget);if(!due||take(compare_world_moments(expiry,*due,c.budget))<=0){due=expiry;basis=ref("military_duty_terms",e.accepted_source_ref);revision=e.service_epoch;}}if(due){if(take(compare_world_moments(*due,current,c.budget))<0)fail("MilitaryDutyUnconsumedDue",row.first);if(take(compare_world_moments(*due,upper,c.budget))<=0)out.push_back({*due,ExactStage::military_duty_period,basis,1,revision});}}return out;});}
Status provide_military_duty_interval(CommonStore& common,MilitaryDutyState& state,const MilitaryDutyContext& c,const MomentSpan& span){return status([&]{std::vector<StableId> active;for(const auto& row:state.executions.rows())if(row.second.current_window_ref)active.push_back(row.first);for(const auto& id:active)take(provide_military_duty_span_in_candidate(common,state,c,id,span));});}
Outcome<ExactEventApplied> apply_military_duty_event(CommonStore& common,MilitaryDutyState& state,const MilitaryDutyContext& c,const ExactEventPrediction& event,ExactPhaseWriteContext& context){return guard<ExactEventApplied>([&]{const auto& source=event.actual_source_basis;if(event.stage!=ExactStage::military_duty_period||source.domain!="military"||event.source_schema!=1)fail("MilitaryDutyActualEventRequired",source.id);if(source.kind=="military_duty_window"){const auto* w=state.windows.find(source.id);if(!w||!std::holds_alternative<DutyWindowOpen>(w->state)||w->window.ordinal!=event.dependency_revision||!same_moment(w->window.planned_close_at,event.at,c.budget))fail("StaleMilitaryDutyWindowPrediction",source.id);const auto id=w->window.duty_action_id;auto* t=state.terms.find(id);if(!t)fail("MilitaryDutyTermsRequired",id);MilitaryDutyQualificationCapture qualification_capture(common);auto q=take(c.original.read_qualification(*t,{event.at,event.at},qualification_capture.prefix()));qualification_capture.validate_unchanged();check_qualification(*t,q);const bool accepted=qualified(rule(c,*t),q);std::optional<MomentOwnerSource> reason=q.unavailable_cause;if(!accepted&&!reason)fail("MilitaryDutyActualInterruptionSourceRequired",id);auto fact=take(close_military_duty_window_in_candidate(common,state,c,id,event.at,accepted?MilitaryDutyDisposition::provided:MilitaryDutyDisposition::interrupted,accepted?std::optional<MomentOwnerSource>{}:reason));if(accepted&&take(compare_world_moments(event.at,until(*t,c.budget),c.budget))<0)take(open_military_duty_window_in_candidate(common,state,c,id,event.at));else if(!accepted)t->state=MilitaryDutyPhase::suspended;return ExactEventApplied{ref("military_duty_period",fact),2};}
if(source.kind=="military_duty_terms"){const auto* accepted=state.accepted_sources.find(source.id);const auto* e=accepted?state.executions.find(accepted->duty_action_id):nullptr;if(!accepted||!e||e->service_epoch!=event.dependency_revision)fail("StaleMilitaryDutyExpiryPrediction",source.id);if(e->actual_binding){const auto result=take(expire_military_movement_duty_in_candidate(common,state,c,accepted->duty_action_id,event.at));return ExactEventApplied{result,1};}const auto* s=station(state,accepted->duty_action_id);if(!s||terminal(state,s->id))fail("MilitaryStationActiveSourceRequired",source.id);const auto action=s->actual_action.id,station_id=s->id;take(expire_military_station_in_candidate(common,state,c,accepted->duty_action_id,event.at,c.release_action));const auto* end=terminal(state,station_id);if(!end)fail("MilitaryStationTerminalRequired",station_id);ActionCompletion complete;complete.completed=true;if(!context.advance.completed_actions.insert(action,std::move(complete)))fail("DuplicateMilitaryStationCompletion",action);return ExactEventApplied{ref("military_station_terminal",end->id),1};}fail("MilitaryDutyEventKindMismatch",source.id);});}
Outcome<std::vector<ExactEventApplied>> invalidate_military_duties_after_original_source(CommonStore& common,MilitaryDutyState& state,const MilitaryDutyContext& c,const MomentOwnerSource& cause,const WorldMoment& at){return guard<std::vector<ExactEventApplied>>([&]{if(!same_moment(take(c.stamps.read_current_moment()),at,c.budget)||!same_moment(take(c.original.read_actual_source_moment(cause)),at,c.budget))fail("MilitaryDutyActualInvalidationCauseRequired",cause.source_ref.id);std::vector<ExactEventApplied> out;for(const auto& stopped:take(consume_military_duty_movement_terminal_in_candidate(common,state,c,cause,at)))out.push_back({stopped,1});std::vector<StableId> active;for(const auto& row:state.executions.rows())if(row.second.current_window_ref)active.push_back(row.first);for(const auto& id:active){auto* t=state.terms.find(id);if(!t)fail("MilitaryDutyTermsRequired",id);MilitaryDutyQualificationCapture qualification_capture(common);auto q=take(c.original.read_qualification(*t,{at,at},qualification_capture.prefix()));qualification_capture.validate_unchanged();check_qualification(*t,q);if(qualified(rule(c,*t),q))continue;if(!q.unavailable_cause)fail("MilitaryDutyActualInvalidationSourceRequired",id);if(q.unavailable_cause->source_schema!=cause.source_schema||!same_source(q.unavailable_cause->source_ref,cause.source_ref))continue;auto result=take(close_military_duty_window_in_candidate(common,state,c,id,at,MilitaryDutyDisposition::interrupted,cause));t->state=MilitaryDutyPhase::suspended;out.push_back({ref("military_duty_period",result),2});}return out;});}
Status validate_military_duty_applied_source(const CommonStore& common,const MilitaryDutyState& state,const MilitaryDutyContext& c,const ExactEventApplied& applied){return status([&]{const auto& ref=applied.applied_result;if(ref.domain!="military")fail("MilitaryDutyAppliedSourceRequired",ref.id);if(ref.kind=="military_duty_execution_stopped"&&applied.source_schema==1){for(const auto& row:state.executions.rows())if(row.second.movement_stop&&row.second.movement_stop->id==ref.id){take(read_military_duty_execution(common,state,c,row.first));return;}fail("MilitaryDutyMovementStopSourceRequired",ref.id);}if(ref.kind=="military_duty_period"){take(read_military_duty_period(common,state,c,ref,applied.source_schema));return;}if(ref.kind=="military_station_terminal"&&applied.source_schema==1){const auto* end=state.station_terminals.find(ref.id);const auto* source=end?state.station_sources.find(end->station_source_ref):nullptr;if(!source)fail("MilitaryStationAppliedTerminalRequired",ref.id);NativeMilitaryStationActionTimeRead read(common,state,c);const auto proof=take(read.read_action_time_owner(military_station_action_time_registration(),source->actual_action.id));if(proof.terminal_result_ref!=std::optional<StableId>{ref.id})fail("MilitaryStationAppliedTerminalMismatch",ref.id);return;}fail("MilitaryDutyAppliedKindMismatch",ref.id);});}
}
